return ['domain'=>'tag-groups','plural-forms'=>'nplurals=4; plural=(n == 1 ? 0 : (n == 2 ? 1 : ((n > 10 && n % 10 == 0) ? 2 : 3)));','language'=>'he_IL','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-17 15:08+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'קבוצות תגיות','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'קבוצות תגיות מאפשרות לך לארגן את מונחי הטקסונומיה של ה-WordPress שלך ולהציג אותם בעננים, טאבים, אקורדים, טבלאות, רשימות ועוד הרבה יותר.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'בית','Taxonomies'=>'טקסונומיות','Front End'=>'חלק קדמי','Back End'=>'חלק אחורי','First Steps'=>'צעדים ראשונים','Setup Wizard'=>'אשף התקנה','Settings'=>'הגדרות','Tag Group Admin'=>'מנהל קבוצת תגיות','The term has been removed from all groups.'=>'המונח הוסר מכל הקבוצות.','Edit this item inline'=>'ערוך פריט זה בשטח','Quick&nbsp;Edit'=>'עריכה מהירה&nbsp;','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'אנא <a %s>לחץ כאן כדי להריץ את שגרת ההגירה</a> כדי לוודא שהיגרנו את כל התגיות.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'ההגדרות/קבוצות שלך והמונחים שלך ייצאו. אנא הורד את הקבצים התוצאה על ידי לחיצה עם העכבר הימני או ctrl-click:','Writing of the exported settings failed.'=>'כתיבת ההגדרות המיוצאות נכשלה.','The groups have been sorted alphabetically.'=>'הקבוצות ממוינות בסדר אלפביתי.','The label cannot be empty.'=>'הכותרת לא יכולה להיות ריקה.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'קבוצת התגים עם הכותרת \'%s\' כבר קיימת, או שהכותרת לא השתנתה. אנא בחר אחת אחרת או חזור אחורה.','A new tag group with the label \'%s\' has been created!'=>'קבוצת תגים חדשה עם הכותרת \'%s\' נוצרה!','A tag group with the label \'%s\' already exists.'=>'קבוצת התגים עם הכותרת \'%s\' כבר קיימת.','The tag group with the label \'%s\' has been saved!'=>'קבוצת התגים עם הכותרת \'%s\' נשמרה!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'קבוצת התגים עם ה-ID %1$s והכותרת \'%2$s\' נמחקה.','Error uploading the file.'=>'שגיאה בהעלאת הקובץ.','Error reading the file.'=>'שגיאה בקריאת הקובץ.','Error parsing the file.'=>'שגיאה בפיענוח הקובץ.','date unknown'=>'תאריך לא ידוע','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'ההגדרות והקבוצות שלך יובאו מהקובץ %1$s (נוצר עם גרסת התוסף %2$s בתאריך %3$s).','%d option was added or changed.'=>'%d אפשרות נוספה או שונתה.' . "\0" . '%d אפשרויות נוספו או שונו.' . "\0" . '' . "\0" . '','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'המונחים שלך יובאו מהקובץ %1$s (נוצר עם גרסת התוסף %2$s בתאריך %3$s).','We processed %d term.'=>'טיפלנו ב-%d מונח.' . "\0" . 'טיפלנו ב-%d מונחים.' . "\0" . '' . "\0" . '','We saved %d term.'=>'שמרנו %d מונח.' . "\0" . 'שמרנו %d מונחים.' . "\0" . '' . "\0" . '','The group info of %d term was updated.'=>'מידע הקבוצה של %d מונח עודכן.' . "\0" . 'מידע הקבוצה של %d מונחים עודכן.' . "\0" . '' . "\0" . '','Filters'=>'מסננים','Gutenberg'=>'גוטנברג','Multilingual'=>'רב-לשוני','Shortcodes'=>'קודים קצרים','Themes and Appearance'=>'נושאים ומראה','remove'=>'הסר','(recommended)'=>'(מומלץ)','keep'=>'שמור','use unfiltered_html filter'=>'השתמש במסנן unfiltered_html','First Aid'=>'עזרה ראשונה','REST API'=>'REST API','System Information'=>'מידע על המערכת','Debugging'=>'דיבוג','Export/Import'=>'ייצוא/ייבוא','Reset'=>'לאפס','Licences'=>'רישיונות','Transients'=>'זמניים','Database'=>'מסד נתונים','Filesystem'=>'מערכת קבצים','WP Object Cache'=>'מטמון אובייקטים של WP','Your settings have been saved.'=>'ההגדרות שלך נשמרו.','Your settings has been saved.'=>'ההגדרות שלך נשמרו.','All groups have been deleted and assignments reset.'=>'כל הקבוצות נמחקו וההקצאות אופסו.','The filter on the tags page has been reset to show all tags.'=>'המסנן בדף התגים אופס כדי להראות את כל התגים.','tag groups'=>'קבוצות תגיות','tag cloud'=>'ענן תגיות','group info'=>'מידע על הקבוצה','sidebar widget'=>'וידג\'ט של סרגל צד','accordion'=>'אקורדיון','tabs'=>'כרטיסיות','alphabetical'=>'אלפביתית','post list'=>'רשימת פוסטים','colors'=>'צבעים','tag description'=>'תיאור תג','tag filter'=>'מסנן תג','post filter'=>'מסנן פוסטים','backup'=>'גיבוי','remove plugin'=>'הסרת תוסף','remove data'=>'הסרת נתונים','delete groups'=>'מחק קבוצות','debugging'=>'ניפוי שגיאות','PHP Version'=>'גרסת PHP','Ajax Test'=>'בדיקת Ajax','troubleshooting'=>'פתרון בעיות','benchmarks'=>'מדדים','speed test'=>'בדיקת מהירות','error'=>'שגיאה','testing'=>'בדיקה','help'=>'עזרה','Tag Groups Pro'=>'קבוצות תגיות פרו','upgrade'=>'שדרוג','more groups'=>'עוד קבוצות','posts'=>'פוסטים','filter'=>'מסנן','animated'=>'אנימטיבי','searchable'=>'בר חיפוש','Info'=>'מידע','author'=>'מחבר','version'=>'גרסה','contact'=>'צור קשר','about'=>'אודות','Licenses'=>'רישיונות','Credits'=>'קרדיטים','Development News'=>'חדשות פיתוח','blog'=>'בלוג','updates'=>'עדכונים','getting started'=>'התחלה','introduction'=>'מבוא','sample'=>'דוגמה','migrate'=>'להעביר','problem'=>'בעיה','live block preview'=>'תצוגה מקדימה של בלוק חי','translation'=>'תרגום','Migrating the term meta'=>'העברת המונח מטה','Fixing incorrect tag groups'=>'תיקון קבוצות תגיות לא נכונות','Fixing incorrect groups in term meta'=>'תיקון קבוצות לא נכונות במונח מטה','Sorting groups in term meta'=>'מיון קבוצות במונח מטה','Checking the tag names'=>'בדיקת שמות התגיות','Start'=>'התחל','Sample Content'=>'תוכן לדוגמה','Sample Group A'=>'קבוצת דוגמה א\'','Sample Group B'=>'קבוצת דוגמה ב\'','Sample Group C'=>'קבוצת דוגמה ג\'','First Sample Tag'=>'תג דוגמה ראשון','Second Sample Tag'=>'תג דוגמה שנייה','Third Sample Tag'=>'תג דוגמה שלישית','Create a draft sample page with Gutenberg blocks.'=>'צור דף דוגמה טיוטה עם בלוקים של גוטנברג.','Create a draft sample page with shortcodes.'=>'צור דף דוגמה טיוטה עם קודים קצרים.','The plugin %1$s requires WordPress %2$s to function properly.'=>'הפלאגין %1$s דורש WordPress %2$s כדי לפעול כראוי.','Please upgrade WordPress and then try again.'=>'אנא עדכן את WordPress ואז נסה שוב.','not assigned'=>'לא הוקצה','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'אתה משתמש בקבוצות תגיות חינם. הגרסה המקצועית כוללת יותר תכונות ותמיכה. %1$sשדרג לגרסה מקצועית%2$s','Upgrade to Pro'=>'שדרג לגרסה מקצועית','Upgrade to Tag Groups Pro'=>'שדרג ל-Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'שפר את כוחם של Tag Groups עם הגרסה המקצועית:','21 Shortcodes'=>'21 קודים קצרים','18 Gutenberg Blocks'=>'18 בלוקים של גוטנברג','Table Tag Cloud'=>'ענן תגי טבלה','Simple Tag Cloud'=>'ענן תגי פשוט','Shuffle Box'=>'תיבת ערבוב','Caching'=>'מטמון','Multiple Groups Per Tag'=>'מספר קבוצות לכל תג','Tag Cloud Search'=>'חיפוש בענן תגים','Toggle Post Filter'=>'החלף מסנן פוסטים','Dynamic Post Filter'=>'מסנן פוסטים דינמי','Post List'=>'רשימת פוסטים','Tag Meta Box'=>'תיבת מטא תג','Post Tags in Groups'=>'תגי פוסטים בקבוצות','Permissions'=>'הרשאות','Default Groups'=>'קבוצות ברירת מחדל','WooCommerce Attributes'=>'מאפייני WooCommerce','Parent Group Level'=>'רמת קבוצת ההורה','Need Tag Groups Support?'=>'צריך תמיכה בקבוצות תג?','If you need help or have a new feature request, let us know.'=>'אם אתה צריך עזרה או יש לך בקשה לתכונה חדשה, הודע לנו.','Request Support'=>'בקשת תמיכה','Detailed documentation is also available on the plugin website.'=>'תיעוד מפורט זמין גם באתר התוסף.','View Knowledge Base'=>'צפה במאגר הידע','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'תוסף קבוצות התג החינמי לא יכול להיות פעיל יחד עם קבוצות התג פרו.','more information'=>'מידע נוסף','Edit tag groups'=>'ערוך קבוצות תג','Clicking will leave this page without saving.'=>'לחיצה תעזוב את הדף הזה מבלי לשמור.','Welcome to %s!'=>'ברוך הבא ל%s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'התוסף מוכן לשימוש. אם אתה צריך עזרה, נוכל להדריך אותך דרך הצעדים הבסיסיים.','Start the Setup Wizard'=>'התחל את אשף ההגדרה','Or click here if you prefer to do it on your own.'=>'או לחץ כאן אם אתה מעדיף לעשות את זה בעצמך.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'עבור אל <span class="dashicons dashicons-tag"></span>&nbsp;הגדרות taxonomy <a %s>של קבוצות תגיות</a> וב<b>בחר את taxonomy</b> (סוג תג) של התגיות שלך. ברוב המקרים פשוט השאר את ברירת המחדל: Tags (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'עבור אל עמוד הניהול של קבוצות התגיות ו<b>צור כמה קבוצות</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'אתה יכול למצוא את העמודים הללו ברשימה בדף הבית של <a %s>קבוצות תגיות</a> שלך.','Go to your tags and <b>assign them to these groups</b>.'=>'עבור אל התגיות שלך ו<b>הקצה אותן לקבוצות הללו</b>.','Filter by tag group'=>'סנן לפי קבוצת תגיות','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s יצר את עמוד הדוגמה הזה במדריך ההתקנה של <b>קבוצות תגיות</b> התוסף. אתה יכול לערוך ולמחוק אותו בבטחה או לשמור אותו לעיון עתידי.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'הקודים הקצרים הבאים משתמשים במגוון פרמטרים כך שתוכל לקבל מושג על האפשרויות. אל תהסס ליצור עמוד דוגמה חדש עם יותר תכנים לאחר שדרוג התוסף.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'אנא מצא קישורים לתיעוד ב<a %s>הגדרות קבוצות תגיות</a>.','Tabbed Tag Cloud'=>'ענן תגיות בכרטיסיות','Accordion Tag Cloud'=>'ענן תגיות באקורדיון','Alphabetical Tag Cloud'=>'ענן תגיות באלף-בית','Tag List'=>'רשימת תגיות','Alphabetical Tag Index'=>'אינדקס תגיות באלף-בית','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'הבלוקים הבאים משתמשים במגוון פרמטרים כך שתוכל לקבל מושג על האפשרויות. אל תהסס ליצור עמוד דוגמה חדש עם יותר תכנים לאחר שדרוג התוסף.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'עמוד זה נוצר כאשר היה לך את עורך גוטנברג פעיל. לכן, התכונות מוצגות רק כאשר גוטנברג פעיל.','Display filter on the "Posts" screen.'=>'הצג סנן על מסך "פוסטים".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'הוסף תפריט נפתח לסינונים מעל רשימת הפוסטים. אם אתה מסנן פוסטים לפי קבוצות תגיות, אז רק פריטים שיש להם תגיות (מונחים) באותה קבוצה יוצגו. תכונה זו יכולה להיות מושבתת כך שהתפריט לא יפריע למסך שלך אם אתה משתמש במספר גבוה של קבוצות. ייתכן שלא תעבוד עם כל ה-taxonomies.','Display filter on the "Tags" screen.'=>'הצג סנן על מסך "תגיות".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'הוסף סנן לרשימת התגיות. השבת אותו כאן אם הוא מתנגש עם תוספים או תבניות אחרות.','Save Settings'=>'שמור הגדרות','Gutenberg block preview'=>'תצוגה מקדימה של בלוק גוטנברג','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'חלק מהבלוקים יכולים להציג תצוגה מקדימה משוערת בעורך גוטנברג. אם תכבה אפשרות זו, כל הבלוקים יראו אייקון סטטי עם טקסט.','Keep groups of translations in sync'=>'שמור קבוצות של תרגומים מסונכרנות','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'אם תפעיל אפשרות זו, אנו ננסה לסנכרן את הקבוצות בכל גרסאות השפה של תג כאשר תישמור אותו. כבה את זה כדי לקבוע קבוצות באופן עצמאי.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'כל תכונות קבוצות התגים זמינות כבלוקים של גוטנברג. תוכל גם להשתמש בקודים קצרים.','Click on the features for more information.'=>'לחץ על התכונות למידע נוסף.','Display the tags in a tabbed tag cloud.'=>'הצג את התגים בענן תגים עם טאבים.','Example'=>'דוגמה','Parameters'=>'פרמטרים','Please find the parameters in the <a %s>documentation</a>.'=>'אנא מצא את הפרמטרים ב-<a %s>תיעוד</a>.','Accordion'=>'אקורדיון','Display the tags in an accordion.'=>'הצג את התגים באקורדיון.','Display the tags in lists under tag groups.'=>'הצג את התגים ברשימות תחת קבוצות תגים.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'הצג את התגים בענן תגים עם טאבים של אותיות ראשונות.','(Not tested with right-to-left languages.)'=>'(לא נבדק עם שפות מימין לשמאל.)','Display the tags in a list with first letters as heading.'=>'הצג את התגים ברשימה עם אותיות ראשונות ככותרת.','Group Information'=>'מידע על הקבוצה','Display information about tag groups.'=>'הצג מידע על קבוצות התגים.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'הפונקציה <b>tag_groups_cloud</b> מקבלת את אותם פרמטרים כמו הקוד הקצר [tag_groups_cloud], למעט אלו שקובעים טאבים ועיצוב.','By default it returns a string with the html for a tabbed tag cloud.'=>'ברירת מחדל מחזירה מיתר עם ה-html עבור ענן תגיות עם טאבים.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'אם הפרמטר השני האופציונלי מוגדר ל- \'true\', הפונקציה מחזירה מערך רב-ממדי המכיל קבוצות תגיות ותגיות.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'אפשר shortcode בווידג\'טים של הצד (אם הוא לא נראה בכל מקרה).','Always load shortcode scripts.'=>'טען תמיד את הסקריפטים של shortcode.','Click for more information'=>'לחץ למידע נוסף','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'כבה כדי לטעון את הסקריפטים רק בפוסטים ודפים שבהם מופיע shortcode.','Turn on if you use these shortcodes in widgets.'=>'הפעל אם אתה משתמש ב-shortcodes האלה בווידג\'טים.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'כאן תוכל לבחור ערכת נושא עבור ענן תגיות עם טאבים ועבור ענן תגיות אקורדיון.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'ניתן ליצור ערכות נושא חדשות עם ה- <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'בעמוד "Theme Roller" תוכל להתאים אישית את כל הפיצ\'רים או לבחור סט אחד מהגלריה. סיים עם כפתור "הורדה".','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'בעמוד הבא ("Download Builder") תצטרך לבחור את הגרסה 1.12.x ואת הרכיבים "Widget", "Accordion" ו-"Tabs". ודא שלפני ההורדה אתה מכניס למטה בתור "CSS Scope" <b>.tag-groups-cloud</b> (כולל את הנקודה).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'אחר כך תפרוס את קובץ ה-zip שהורדת. תצטרך את תיקיית "images" ואת הקובץ "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'צור תיקיה חדשה בתוך תיקיית <i>wp-content/uploads</i> שלך (למשל "my-theme") והעתק לשם את שני הפריטים האלה.','Enter the name of this new folder (for example "my-theme") below.'=>'הכנס את שם התיקיה החדשה הזו (למשל "my-theme") למטה.','own theme'=>'ערכת נושא משלה','Don\'t load a theme.'=>'אל תטען ערכת נושא.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'כאן תוכל לכבות ערכות נושא של jQuery UI אם ערכת הנושא של WordPress שלך מביאה את ערכת הנושא של jQuery UI שלה, כדי להימנע מעימותים.','Further options'=>'אפשרויות נוספות','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'השתמש ב-jQuery.  (ברירת המחדל היא מופעלת. תוספים אחרים עשויים להחליף הגדרה זו.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'טאבים המופעלים על ידי ריחוף סמן העכבר (בלי לחיצה).','Collapsible tabs (toggle open/close).'=>'כרטיסיות ניתנות לקיפול (ממתג פתיחה/סגירה).','HTML in tag description:'=>'HTML בתיאור תג:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'ברירת מחדל התיאור מופיע בטיפ עכבר כאשר אתה מרחף מעל תג בענן תגיות.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'אם אינך סומך על כל המשתמשים באתר שלך, הסר את ה-HTML או השתמש בתוסף כדי לתת את יכולת unfiltered_html רק למשתמשים שאתה סומך עליהם.','Save Theme Options'=>'שמור אפשרויות ערכת נושא','Search for settings'=>'חפש הגדרות','Search for setting pages. Type a space to show all settings.'=>'חפש דפי הגדרות. הקלד רווח כדי להראות את כל ההגדרות.','Search Results'=>'תוצאות חיפוש','Nothing found'=>'לא נמצא דבר','Active Taxonomies'=>'טקסונומיות פעילות','Group Statistics'=>'סטטיסטיקות קבוצה','for the selected language'=>'בשפה שנבחרה','go to tag group administration'=>'עבור לניהול קבוצות תג','Enable Tag Groups Public API Access'=>'אפשר גישה ציבורית ל-API של קבוצות תג','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'אפשר גישה ציבורית לנקודת הקצה של קבוצות תג /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'אפשר גישה ציבורית ל-API של מונחים','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'אפשר גישה ציבורית לנקודת הקצה של מונחים /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'בחר את הטקסונומיות שברצונך להשתמש בהן עבור קבוצות תג:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'הטקסונומיה ברירת המחדל היא <b>Tags (post_tag)</b>. שים לב כי ענני התגים עשויים שלא לפעול עם כל הטקסונומיות וכי חלק מהטקסונומיות המפורטות כאן עשויות שלא להיות נגישות בחלק האחורי של המנהל. אם אינך מבין מה קורה כאן, פשוט השאר את ברירת המחדל.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>אנא הסר את הסימון מטקסונומיות שאינך משתמש בהן. השימוש בכמה טקסונומיות עבור אותו סוג פוסט או טקסונומיות היררכיות (כמו קטגוריות) הוא ניסי ואינו נתמך.</b>','To see the post type, hover your mouse over the option.'=>'כדי לראות את סוג הפוסט, ר hover את העכבר שלך מעל האפשרות.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'אם אתה משתמש ב-taxonomy מותאם אישית, ודא שהמאפיין "Public" מוגדר כ-"true" ו-"Hierarchical" כ-"false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'הצג taxonomies היררכיות. לא כל התכונות של קבוצות התגים יעבדו עם ה-taxonomies הללו.','Save Taxonomies'=>'שמור Taxonomies','Export'=>'ייצא','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'השתמש בלחצן זה כדי לייצא את כל הגדרות קבוצות התגים וכל המונחים שמוקצים לקבוצה לקבצים.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'אתה יכול לייבא את שני הקבצים בנפרד. היררכיית הקטגוריות לא תישמר. כאשר אתה משחזר מונחים שנמחקו, הם מקבלים מזהים חדשים ואתה חייב להקצות אותם לפוסטים שוב. ייצוא לא יכול להחליף גיבוי.','Export Files'=>'קבצי ייצוא','Import'=>'ייבא','Below you can import previously exported settings/groups or terms from a file.'=>'למטה אתה יכול לייבא הגדרות/קבוצות או מונחים שהופקו בעבר מקובץ.','It is recommended to back up the database of your site before proceeding.'=>'מומלץ לגבות את מסד הנתונים של האתר שלך לפני ההמשך.','Please import the settings before the terms.'=>'אנא ייבא את ההגדרות לפני המונחים.','Import File'=>'ייבא קובץ','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'השתמש בלחצן זה כדי למחוק את כל קבוצות התגים וההקצות. התגים שלך לא ישתנו. סמן את תיבת הסימון כדי לאשר.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'אנא שים לב שההקצות של התגים לא יכולות להיות משוחזרות על ידי פונקציית הייצוא/ייבוא.','I know what I am doing.'=>'אני יודע מה אני עושה.','Delete Groups'=>'מחק קבוצות','Delete Settings and Groups'=>'מחק הגדרות וקבוצות','Delete all groups and settings when uninstalling the plugin.'=>'מחק את כל הקבוצות וההגדרות כאשר אתה מסיר את התוסף.','Debug mode is on.'=>'מצב דיבוג פעיל.','Verbose logging is enabled with CM_DEBUG.'=>'רישום מפורט מופעל עם CM_DEBUG.','Verbose logging is on.'=>'רישום מפורט פעיל.','Turn off '=>'כבה ','Verbose logging is off.'=>'רישום מפורט כבוי.','Turn on'=>'הפעל','Debug mode is off.'=>'מצב ניפוי שגיאות כבוי.','Learn more <a %s>about debugging</a>.'=>'למידע נוסף <a %s>על ניפוי שגיאות</a>.','Migrate tags to the new format of Tag Groups.'=>'העבר תגיות לפורמט החדש של קבוצות תגיות.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'התוסף מעביר אוטומטית תגיות לפורמט החדש ומנסה לעקוב אחרי השינויים. עם זאת, ייתכן שיש מקרים שבהם רכיבים אחרים ביצעו שינויים שלא נצפו. ייתכן שתצטרך גם להעביר ידנית תגיות לאחר שהפעלת טקסונומיה שכבר הכילה תגיות שלא נעקבו.','Migrate'=>'העבר','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'הרצת תחזוקה יכולה לפתור בעיות שאתה נתקל בהן במהלך סינון לפי קבוצות תגיות.','Maintenance'=>'תחזוקה','Reset the filter on the tags page to show all tags.'=>'אפס את הסינון בעמוד התגיות כדי להראות את כל התגיות.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'השתמש בזה אם שגיאת JavaScript משבשת את תפריט הסינון. שים לב שעדיין מומלץ לגלות את סיבת השגיאה.','Reset Tag Filter'=>'אפס סינון תגיות','Please stay on this page until all processes have finished.'=>'אנא הישאר בדף הזה עד שכל התהליכים יסתיימו.','There have been errors.'=>'היו שגיאות.','Continue'=>'המשך','Finished!'=>'הסתיים!','The following terms cannot be used:'=>'המונחים הבאים לא יכולים לשמש:','Number of processed items: '=>'מספר הפריטים המעובדים: ','Number of changed items: '=>'מספר הפריטים המשתנים: ','WordPress Version'=>'גרסת WordPress','Site URL'=>'כתובת האתר','Home URL'=>'כתובת הבית','Active Theme'=>'עיצוב פעיל','Version'=>'גרסה','Checking...'=>'בודק...','Show the Response'=>'הצג את התגובה','passed'=>'עבר','failed'=>'נכשל','Benchmarks'=>'מדדים','Cache'=>'מטמון','Tag groups pro only'=>'קבוצות תגיות רק עבור פרו','Server'=>'שרת','Constants'=>'קבועים','Well done!'=>'כל הכבוד!','Now go the Tag Group Administration.'=>'עכשיו עבור לניהול קבוצות התגיות.','Or preview the sample page here.'=>'או תצוגה מקדימה של דף הדוגמה כאן.','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'או עבור אל <a %1$s>הגדרות קבוצות תגיות</a> או בקר ב-<a %2$s>תיעוד</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'עכשיו עבור אל <a %1$s>הגדרות קבוצות תגיות</a>, או בקר ב-<a %2$s>תיעוד</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'אם אתה צריך להפעיל מחדש את אשף ההתקנה, תוכל למצוא אותו בהגדרות. פשוט הקלד "wizard" בשדה החיפוש.','Happy tagging!'=>'תגים שמחים!','Tag Groups Setup Wizard'=>'אשף התקנת קבוצות תגים','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'עכשיו אתה מוכן ליצור קבוצות תגים משלך. אם אתה מעדיף להתחיל מדוגמה, ניצור עבורך שלוש קבוצות ושלושה תגים. תוכל לשחק איתן, לשנות את שמן או למחוק אותן.','Create sample groups:'=>'צור קבוצות דוגמה:','Create sample tags in these groups:'=>'צור תגים לדוגמה בקבוצות אלו:','Next Step'=>'צעד הבא','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'בעמודים הבאים ננחה אותך דרך ההגדרות הבסיסיות שאתה צריך עבור התכונות הנפוצות ביותר.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'תוכל מאוחר יותר לבצע שינויים או לדייק את הפרטים בהגדרות קבוצות התגים.','(show me the menu)'=>'(הראה לי את התפריט)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'אל תהסס לבטל את אשף ההתקנה בכל עת ולהמשיך בדרך שלך. תוכל גם להפעיל אותו שוב מאוחר יותר.','The wizard will offer more options after upgrading to premium.'=>'האשף יציע עוד אפשרויות לאחר שדרוג לגרסה פרימיום.','Choose the taxonomies for which you want to use tag groups.'=>'בחר את ה-taxonomies עבורן אתה רוצה להשתמש בקבוצות תגים.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'ברוב המקרים ה-taxonomy ברירת המחדל <b>Tags (post_tag)</b> תעשה את העבודה.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'תמצא עוד אפשרויות בהגדרות קבוצות התגים.','Tag Group Administration'=>'ניהול קבוצת תגים','Filter by label'=>'סנן לפי תווית','Tag Group name'=>'שם קבוצת תגים','Number of assigned tags'=>'מספר התגים שהוקצו','Actions'=>'פעולות','Change order'=>'שנה סדר','Group ID'=>'מזהה קבוצה','Edit'=>'עריכה','Create'=>'צור','new'=>'חדש','label'=>'תווית','Delete this group.'=>'מחק קבוצה זו.','Create a new group below.'=>'צור קבוצה חדשה למטה.','Add New Tag Group'=>'הוסף קבוצת תגיות חדשה','move up'=>'העבר למעלה','move down'=>'העבר למטה','reload'=>'טען מחדש','next page'=>'עמוד הבא','previous page'=>'עמוד קודם','go to page:'=>'עבור לעמוד:','Show posts'=>'הצג פוסטים','Show tags'=>'הצג תגיות','Do you really want to delete this tag group?'=>'האם אתה באמת רוצה למחוק את קבוצת התגיות הזו?','Please visit <a %1$s>%2$s</a>.'=>'אנא בקרו <a %1$s>%2$s</a>.','Read more'=>'קרא עוד','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'תודה שהשתמשת בקבוצות תגיות | %1$sTaxoPress.com%2$s | גרסה %3$s','Assign to'=>'הקצה ל','Filter off'=>'מסנן כבוי','Please select one of the languages above to see the correct tag groups!'=>'אנא בחר אחת מהשפות למעלה כדי לראות את קבוצות התגיות הנכונות!','Groups'=>'קבוצות']];